const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const radar=document.getElementById('radar'),rctx=radar.getContext('2d');
const overlay=document.getElementById('overlay'),hud=document.getElementById('hud'),result=document.getElementById('result');
const TAU=Math.PI*2, FOV=Math.PI*.39;
const mapText=[
'###################',
'#........#........#',
'#........#........#',
'#.................#',
'#..##........##...#',
'#..##........##...#',
'#.................#',
'###...##..##...#####',
'#.................#',
'#.................#',
'#####...##..##...###',
'#.................#',
'#.................#',
'#...##........##..#',
'#...##........##..#',
'#........#........#',
'#........#........#',
'#.................#',
'###################'];
const MAP=mapText.map(row=>row.split('').map(c=>c==='#'?1:0));
const W=MAP[0].length,H=MAP.length;
let vw=innerWidth,vh=innerHeight,dpr=1;
function resize(){dpr=Math.min(devicePixelRatio||1,1.5);vw=innerWidth;vh=innerHeight;canvas.width=Math.floor(vw*dpr);canvas.height=Math.floor(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);radar.width=radar.clientWidth*dpr;radar.height=radar.clientHeight*dpr;rctx.setTransform(dpr,0,0,dpr,0,0)}
addEventListener('resize',resize);resize();
const wallTex=document.createElement('canvas');wallTex.width=128;wallTex.height=128;const wt=wallTex.getContext('2d');
wt.fillStyle='#a58c64';wt.fillRect(0,0,128,128);wt.fillStyle='#95815f';
for(let y=0;y<128;y+=24){wt.fillRect(0,y,128,2);let off=(Math.floor(y/24)%2)*32;for(let x=off;x<128;x+=64)wt.fillRect(x,y,2,24)}
wt.fillStyle='rgba(232,204,150,.13)';for(let y=5;y<128;y+=24)for(let x=5;x<128;x+=64)wt.fillRect(x,y,30,1);
wt.fillStyle='rgba(50,42,29,.26)';for(let i=0;i<130;i++){let x=Math.random()*128,y=Math.random()*128;wt.fillRect(x,y,Math.random()*2+1,Math.random()*5+1)}
const player={x:9.5,y:9.4,a:-Math.PI/2,hp:100,ammo:30,reserve:90};
let bots=[],particles=[],keys={},state='menu',last=performance.now(),elapsed=0,gameTime=90,fireAt=0,reloading=false,reloadAt=0,shotFlash=0,shake=0,kills=0,mouseDown=false,feedTimer=0;
const spawns=[{x:3.5,y:3.4},{x:15.5,y:3.6},{x:3.6,y:15.1},{x:15.5,y:15.2},{x:9.4,y:2.6}];
function resetGame(){player.x=9.5;player.y=9.4;player.a=-Math.PI/2;player.hp=100;player.ammo=30;player.reserve=90;kills=0;elapsed=0;gameTime=90;reloading=false;fireAt=0;bots=spawns.map((p,i)=>({x:p.x,y:p.y,hp:100,alive:true,hit:0,attack:Math.random()*1.4,seed:i*3.77,phase:Math.random()*6,alert:false}));document.getElementById('remaining').textContent='05';document.getElementById('feed').innerHTML='';updateHud()}
function startGame(){resetGame();state='playing';overlay.classList.add('hidden');result.classList.remove('show');hud.classList.add('active');document.getElementById('statusText').textContent='HOSTILES ACTIVE';canvas.requestPointerLock?.();}
document.getElementById('startBtn').onclick=startGame;document.getElementById('againBtn').onclick=startGame;
function endGame(won){if(state!=='playing')return;state='result';document.exitPointerLock?.();document.getElementById('resultEyebrow').textContent=won?'OPERATION COMPLETE':'MISSION FAILED';document.getElementById('resultTitle').textContent=won?'YARD SECURED':'OPERATOR DOWN';document.getElementById('resultText').textContent=won?`All hostiles neutralized. ${Math.round(elapsed)} seconds on the clock.`:'The yard is still hostile. Regroup and try again.';result.classList.add('show');hud.classList.remove('active')}
function wall(x,y){let ix=Math.floor(x),iy=Math.floor(y);return ix<0||iy<0||ix>=W||iy>=H||MAP[iy][ix]===1}
function normAngle(a){while(a>Math.PI)a-=TAU;while(a< -Math.PI)a+=TAU;return a}
function blocked(x,y,r=.2){return wall(x-r,y-r)||wall(x+r,y-r)||wall(x-r,y+r)||wall(x+r,y+r)}
function clearShot(x1,y1,x2,y2){let dx=x2-x1,dy=y2-y1,dist=Math.hypot(dx,dy),steps=Math.ceil(dist*12);for(let i=1;i<steps;i++){let t=i/steps;if(wall(x1+dx*t,y1+dy*t))return false}return true}
function updateHud(){document.getElementById('healthNum').textContent=Math.ceil(player.hp);document.getElementById('healthBar').style.width=Math.max(0,player.hp)+'%';document.getElementById('ammoNum').textContent=player.ammo;document.getElementById('reserveNum').textContent=player.reserve;document.getElementById('remaining').textContent=String(bots.filter(b=>b.alive).length).padStart(2,'0')}
function reload(){if(state!=='playing'||reloading||player.ammo===30||player.reserve<=0)return;reloading=true;reloadAt=performance.now()/1000+1.35;document.getElementById('statusText').textContent='RELOADING';}
function fire(){let now=performance.now()/1000;if(state!=='playing'||reloading||now-fireAt<.17)return;if(player.ammo<=0){reload();return}fireAt=now;player.ammo--;shotFlash=.09;shake=2.2;let best=null,bestScore=99;for(const b of bots){if(!b.alive)continue;let dx=b.x-player.x,dy=b.y-player.y,dist=Math.hypot(dx,dy),ang=Math.abs(normAngle(Math.atan2(dy,dx)-player.a));let score=ang+(dist*.002);if(ang<.11+dist*.0025&&dist<17&&score<bestScore&&clearShot(player.x,player.y,b.x,b.y)){best=b;bestScore=score}}
if(best){best.hp-=bestScore<.025?100:55;best.hit=.18;best.alert=true;document.getElementById('hitmarker').classList.add('show');setTimeout(()=>document.getElementById('hitmarker').classList.remove('show'),100);if(best.hp<=0){best.alive=false;kills++;addFeed('HOSTILE DOWN','+100');if(!bots.some(b=>b.alive)){document.getElementById('statusText').textContent='SECTOR CLEAR';setTimeout(()=>endGame(true),850)}}else addFeed('TARGET HIT','−55')}else addFeed('');updateHud()}
function addFeed(text){if(!text)return;let feed=document.getElementById('feed'),d=document.createElement('div');d.textContent='✦  '+text;feed.prepend(d);while(feed.children.length>3)feed.lastChild.remove();setTimeout(()=>d.remove(),2300)}
function movePlayer(dt){let f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),s=(keys.KeyD?1:0)-(keys.KeyA?1:0);if(stickVector.active){f+=-stickVector.y;s+=stickVector.x}let l=Math.hypot(f,s);if(l){f/=l;s/=l}let speed=(keys.ShiftLeft||keys.ShiftRight?4.7:3.05);let dx=(Math.cos(player.a)*f-Math.sin(player.a)*s)*speed*dt,dy=(Math.sin(player.a)*f+Math.cos(player.a)*s)*speed*dt;if(!blocked(player.x+dx,player.y,.22))player.x+=dx;if(!blocked(player.x,player.y+dy,.22))player.y+=dy}
function moveBots(dt){for(let i=0;i<bots.length;i++){let b=bots[i];if(!b.alive)continue;b.hit=Math.max(0,b.hit-dt);b.phase+=dt;let dx=player.x-b.x,dy=player.y-b.y,d=Math.hypot(dx,dy);if(d<10&&clearShot(b.x,b.y,player.x,player.y))b.alert=true;if(b.alert&&d>2.4){let sp=1.05+(.12*Math.sin(b.phase*2)),vx=dx/d*sp*dt,vy=dy/d*sp*dt;if(!blocked(b.x+vx,b.y,.24))b.x+=vx;else if(!blocked(b.x,b.y+vy,.24))b.y+=vy;else if(!blocked(b.x+vy,b.y,.24))b.x+=vy;if(!blocked(b.x,b.y+vy,.24))b.y+=vy}if(b.alert&&d<9&&d>1.8){b.attack-=dt;if(b.attack<=0&&clearShot(b.x,b.y,player.x,player.y)){b.attack=1.3+Math.random()*.8;player.hp=Math.max(0,player.hp-(5+Math.random()*5));shake=2;addFeed('INCOMING FIRE');updateHud();if(player.hp<=0)endGame(false)}}}}
function raycast(angle){let dx=Math.cos(angle),dy=Math.sin(angle),mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/(dx||1e-9)),ddy=Math.abs(1/(dy||1e-9)),sx=dx<0?-1:1,sy=dy<0?-1:1,sdx=(dx<0?player.x-mx:mx+1-player.x)*ddx,sdy=(dy<0?player.y-my:my+1-player.y)*ddy,side=0,dist=20;for(let i=0;i<60;i++){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}if(mx<0||my<0||mx>=W||my>=H||MAP[my][mx]){dist=side===0?sdx-ddx:sdy-ddy;break}}let hit=side===0?player.y+dist*dy:player.x+dist*dx,tex=hit-Math.floor(hit);if((side===0&&dx>0)||(side===1&&dy<0))tex=1-tex;return{dist:Math.max(.001,dist*Math.cos(angle-player.a)),raw:dist,side,tex,mx,my}}

function drawBot(b,depth,x){let s=Math.min(1,Math.max(.25,7/depth)),w=32*s,h=76*s,headY=-h*.43,hit=b.hit>0;ctx.save();ctx.translate(x,0);ctx.globalAlpha=Math.min(1,11/depth);ctx.fillStyle='rgba(15,18,14,.32)';ctx.beginPath();ctx.ellipse(0,vh*.52,w*.56,5*s,0,0,TAU);ctx.fill();ctx.translate(0,vh*.51);ctx.scale(s,s);
// boots and legs
ctx.fillStyle=hit?'#d85c46':'#393b32';ctx.beginPath();ctx.moveTo(-11,-15);ctx.lineTo(-8,-43);ctx.lineTo(-1,-43);ctx.lineTo(0,-16);ctx.lineTo(-3,-8);ctx.lineTo(-14,-8);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(2,-16);ctx.lineTo(4,-43);ctx.lineTo(11,-43);ctx.lineTo(13,-15);ctx.lineTo(18,-8);ctx.lineTo(5,-8);ctx.closePath();ctx.fill();
// body vest
let grad=ctx.createLinearGradient(-18,-73,17,-23);grad.addColorStop(0,hit?'#db654e':'#727258');grad.addColorStop(1,hit?'#73372e':'#353b32');ctx.fillStyle=grad;ctx.beginPath();ctx.moveTo(-11,-70);ctx.lineTo(10,-70);ctx.lineTo(17,-39);ctx.lineTo(11,-26);ctx.lineTo(-12,-26);ctx.lineTo(-17,-39);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(15,19,15,.8)';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#252a25';ctx.fillRect(-10,-52,20,11);ctx.fillStyle='#a5a17a';ctx.fillRect(-3,-66,6,3);ctx.fillStyle='#858267';ctx.fillRect(-13,-45,5,8);ctx.fillRect(8,-45,5,8);
// arms
ctx.strokeStyle=hit?'#e97c62':'#6d6c53';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-12,-64);ctx.lineTo(-22,-45);ctx.lineTo(-13,-38);ctx.moveTo(12,-64);ctx.lineTo(22,-47);ctx.lineTo(12,-41);ctx.stroke();
// rifle
ctx.fillStyle='#171d1a';ctx.fillRect(3,-47,27,4);ctx.fillRect(10,-51,9,3);ctx.fillStyle='#858771';ctx.fillRect(23,-47,12,2);ctx.fillRect(4,-45,6,7);
// head + helmet
ctx.fillStyle='#b48c69';ctx.beginPath();ctx.arc(0,-77,9,0,TAU);ctx.fill();ctx.fillStyle='#555a44';ctx.beginPath();ctx.ellipse(0,-83,12,6,0,Math.PI,TAU);ctx.fill();ctx.fillRect(-10,-83,20,3);ctx.fillStyle='#18201b';ctx.fillRect(-5,-78,10,3);ctx.restore()}
function drawWeapon(){let x=vw*.69,y=vh+30;ctx.save();let kick=shotFlash>0?13:0;if(reloading)kick=Math.sin((1-(reloadAt-performance.now()/1000)/1.35)*Math.PI)*38;ctx.translate(x,y+kick);ctx.rotate(-.07);
let g=ctx.createLinearGradient(0,-200,180,0);g.addColorStop(0,'#1b2420');g.addColorStop(.42,'#4e5850');g.addColorStop(.65,'#242c28');g.addColorStop(1,'#111714');
// forearm
ctx.fillStyle='#80644e';ctx.beginPath();ctx.moveTo(62,-5);ctx.lineTo(145,-9);ctx.lineTo(170,44);ctx.lineTo(98,80);ctx.closePath();ctx.fill();ctx.fillStyle='#333a34';ctx.fillRect(64,-73,180,41);ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(28,-75);ctx.lineTo(195,-80);ctx.lineTo(209,-25);ctx.lineTo(64,-22);ctx.closePath();ctx.fill();ctx.fillStyle='#151b18';ctx.fillRect(176,-71,143,12);ctx.fillRect(280,-76,50,5);ctx.fillStyle='#687269';ctx.fillRect(110,-88,37,8);ctx.fillRect(124,-98,10,12);ctx.fillStyle='#101613';ctx.fillRect(86,-29,26,45);ctx.fillRect(118,-24,24,61);ctx.fillStyle='#879087';ctx.fillRect(65,-68,105,3);ctx.fillStyle='#121815';ctx.fillRect(206,-62,45,17);ctx.fillStyle='#748078';ctx.fillRect(218,-57,16,5);
if(shotFlash>0){ctx.globalCompositeOperation='screen';ctx.fillStyle='rgba(255,222,142,.92)';ctx.beginPath();ctx.moveTo(320,-73);ctx.lineTo(370,-89);ctx.lineTo(350,-73);ctx.lineTo(374,-56);ctx.lineTo(319,-64);ctx.closePath();ctx.fill();ctx.fillStyle='rgba(255,250,201,.95)';ctx.beginPath();ctx.arc(320,-68,12,0,TAU);ctx.fill()}ctx.restore()}
function drawWorld(){let horizon=vh*.48,shakeX=shake?(Math.random()-.5)*shake:0,shakeY=shake?(Math.random()-.5)*shake:0;ctx.save();ctx.translate(shakeX,shakeY);
let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#697a72');sky.addColorStop(.62,'#b29e79');sky.addColorStop(1,'#d0b181');ctx.fillStyle=sky;ctx.fillRect(-5,-5,vw+10,horizon+8);
// distant depot roofline
ctx.fillStyle='rgba(53,61,53,.42)';ctx.beginPath();ctx.moveTo(0,horizon-12);ctx.lineTo(0,horizon-37);ctx.lineTo(vw*.12,horizon-37);ctx.lineTo(vw*.12,horizon-54);ctx.lineTo(vw*.24,horizon-54);ctx.lineTo(vw*.24,horizon-24);ctx.lineTo(vw*.43,horizon-24);ctx.lineTo(vw*.43,horizon-47);ctx.lineTo(vw*.56,horizon-47);ctx.lineTo(vw*.56,horizon-26);ctx.lineTo(vw*.76,horizon-26);ctx.lineTo(vw*.76,horizon-51);ctx.lineTo(vw*.86,horizon-51);ctx.lineTo(vw*.86,horizon-32);ctx.lineTo(vw,horizon-32);ctx.lineTo(vw,horizon);ctx.closePath();ctx.fill();
let floor=ctx.createLinearGradient(0,horizon,0,vh);floor.addColorStop(0,'#9b815b');floor.addColorStop(.22,'#766145');floor.addColorStop(1,'#252923');ctx.fillStyle=floor;ctx.fillRect(-5,horizon,vw+10,vh-horizon+5);
// ground perspective seams
ctx.strokeStyle='rgba(225,193,142,.11)';ctx.lineWidth=1;for(let i=1;i<10;i++){let yy=horizon+(vh-horizon)*(i/10)**2;ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(vw,yy);ctx.stroke()}for(let i=-6;i<=6;i++){ctx.beginPath();ctx.moveTo(vw/2+i*11,horizon);ctx.lineTo(vw/2+i*vw*.16,vh);ctx.stroke()}
const focal=vw/(2*Math.tan(FOV/2)),step=2,zbuf=[];for(let sx=0;sx<vw;sx+=step){let angle=player.a+Math.atan((sx-vw/2)/focal),r=raycast(angle),dist=r.dist;zbuf[Math.floor(sx/step)]=dist;let height=Math.min(vh*1.6,focal*.9/dist),top=horizon-height*.5,bot=top+height;let tw=wallTex.width,tx=Math.floor(r.tex*tw);ctx.globalAlpha=Math.min(1,1.3/(dist*.12+1));ctx.drawImage(wallTex,tx,0,1,128,sx,top,step+1,height);ctx.globalAlpha=1;
let shade=Math.min(.73,dist*.039)+(r.side?.16:0);ctx.fillStyle=`rgba(11,15,12,${shade})`;ctx.fillRect(sx,top,step+1,height);
// sunlit top rim and warning marks
if(height>44){ctx.fillStyle='rgba(224,203,160,.17)';ctx.fillRect(sx,top,step+1,Math.max(1,height*.018));if(r.mx%5===1&&r.my%4===0){ctx.fillStyle='rgba(205,183,129,.22)';ctx.fillRect(sx,top+height*.24,step+1,Math.max(1,height*.035))}}
}
// dust motes
for(let i=0;i<16;i++){let x=(i*173+elapsed*11)%vw,y=horizon+((i*71)%Math.max(1,vh-horizon));ctx.fillStyle='rgba(242,218,163,.16)';ctx.fillRect(x,y,1.5,1.5)}
// billboards ordered far to near
let visible=bots.filter(b=>b.alive).map(b=>{let dx=b.x-player.x,dy=b.y-player.y,a=normAngle(Math.atan2(dy,dx)-player.a),d=Math.hypot(dx,dy);return{b,a,d,x:vw/2+Math.tan(a)*focal}}).filter(o=>Math.abs(o.a)<FOV*.72&&o.d>0.3).sort((a,b)=>b.d-a.d);
for(let o of visible){let idx=Math.floor(o.x/step);if(o.x<0||o.x>vw||o.d>zbuf[idx]+.2)continue;drawBot(o.b,o.d,o.x)}
// atmospheric overlay
let haze=ctx.createLinearGradient(0,horizon-20,0,horizon+vh*.15);haze.addColorStop(0,'rgba(221,193,146,.04)');haze.addColorStop(1,'rgba(202,167,113,.12)');ctx.fillStyle=haze;ctx.fillRect(0,horizon-20,vw,vh*.18);drawWeapon();ctx.restore()}

