+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');const radar=document.getElementById('radar'),rctx=radar.getContext('2d');const overlay=document.getElementById('overlay'),hud=document.getElementById('hud'),result=document.getElementById('result');
